import { motion } from "framer-motion";

export const formatDate = (dateString) => {
    if (!dateString) return 'N/A';

    const date = new Date(dateString);
    const now = new Date();
    const diffTime = Math.abs(now - date);
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays === 1) {
        return 'Yesterday';
    } else if (diffDays < 7) {
        return `${diffDays} days ago`;
    } else {
        return date.toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'short',
            day: 'numeric'
        });
    }
};

export const formatDateT = (dateString) => {
    if (!dateString) return 'N/A';

    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric'
    });
};

export const formatDateTime = (dateString) => {
    if (!dateString) return 'N/A';

    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
    });
};

export const FormatCurrency = (value) => {
    return `₦${new Intl.NumberFormat('en-NG', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
    }).format(value)}`;
};

export const limitWords = (text, maxWords) => {
    if (!text) return '';
    const words = text.split(' ');
    if (words.length <= maxWords) return text;
    return words.slice(0, maxWords).join(' ') + '...';
};

export const getStatusStyle = (status) => {
    const statusNew = status?.replaceAll('_', ' ')?.toLowerCase();

    switch (statusNew) {
        case 'unfulfilled':
        case 'low stock':
        case 'low_stock':
        case 'scheduled':
        case 'pending':
            return 'bg-[#FFF3CD] text-[#664D03]'
        case 'shipped':
        case 'fulfilled':
            return 'bg-[#CFF4FC] text-[#055160]'
        case 'cancelled':
        case 'expired':
        case 'out of stock':
        case 'out_of_stock':
            return 'bg-[#F8D7DA] text-[#842029]'
        case 'delivered':
        case 'in stock':
        case 'in_stock':
        case 'active':
        case 'sent':
        case 'paid':
            return 'bg-[#D1E7DD] text-[#0F5132]'
        default:
            return 'bg-[#DCDCDC] text-[#777777]'
    }
};

export const CustomTooltip = ({ active, payload }) => {
    if (active && payload && payload.length) {
        const data = payload[0];
        return (
            <motion.div initial={{ opacity: 0, scale: 0.8 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.8 }} className="bg-white p-3 border rounded-lg shadow-lg">
                <p className="font-medium">{data.name}</p>
                <p className="text-xs text-[#000000B2]">{data.value}%</p>
            </motion.div>
        );
    }
    return null;
};

export const CustomLegend = ({ payload }) => {
    return (
        <div className="flex flex-col gap-2 mt-4">
            {payload.map((entry, index) => (
                <motion.div key={index} initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: index * 0.1 }} className="flex items-center gap-3">
                    <div className="w-4 h-4 rounded-full" style={{ backgroundColor: entry.color }} />
                    <span className="text-xs font-medium text-gray-700">
                        {entry.value} ({payload.find(item => item.name === entry.value)?.value}%)
                    </span>
                </motion.div>
            ))}
        </div>
    );
};

export const detectCardType = (cardNumber) => {
    const number = cardNumber.replace(/\s/g, '');
    if (number.match(/^4/)) return 'visa';
    if (number.match(/^5[1-5]/) || number.match(/^2[2-7]/)) return 'mastercard';
    if (number.match(/^(506|650)/)) return 'verve';
    if (number.match(/^3[47]/)) return 'amex';
    if (number.match(/^(6011|644|645|646|647|648|649|65)/)) return 'discover';
    if (number.match(/^35(2[8-9]|[3-8])/)) return 'jcb';
    if (number.match(/^(30|36|38)/)) return 'dinersclub';
    if (number.match(/^62/)) return 'unionpay';
    if (number.match(/^(50|5[6-8]|6)/)) return 'maestro';
    if (number.match(/^627/)) return 'interac';

    return 'unknown';
};

