function extractCountryCode(phone_number) {
    if (!phone_number) return null

    let cleanNumber = phone_number.replace(/[^\d+]/g, "")

    if (cleanNumber.startsWith("+")) {
        cleanNumber = cleanNumber.substring(1)
    }

    const sortedCodes = Object.keys(countryCodeMap).sort(
        (a, b) => b.length - a.length
    )

    for (const code of sortedCodes) {
        if (cleanNumber.startsWith(code)) {
            return code
        }
    }

    return null
}

export function getFlagFromphone_number(phone_number, size = "4x3") {
    const countryCode = extractCountryCode(phone_number)
    const baseUrl =
        "https://raw.githubusercontent.com/lipis/flag-icons/5f40463ce1d8731f4e22dcb8acbc715b01573c54/flags"

    if (!countryCode) {
        return `${baseUrl}/${size}/ng.svg`
    }

    const isoCode = countryCodeMap[countryCode]

    if (!isoCode) {
        return `${baseUrl}/${size}/ng.svg`
    }

    return `${baseUrl}/${size}/${isoCode}.svg`
}

export function getFlagFromCountryName(countryName, size = "4x3") {
    const baseUrl =
        "https://raw.githubusercontent.com/lipis/flag-icons/5f40463ce1d8731f4e22dcb8acbc715b01573c54/flags";

    if (!countryName) {
        return `${baseUrl}/${size}/ng.svg`;
    }

    const country = countries.find(c =>
        c.name.toLowerCase() === countryName.toLowerCase()
    );

    if (!country) {
        return `${baseUrl}/${size}/ng.svg`;
    }

    return `${baseUrl}/${size}/${country.code}.svg`;
}

export function hasValidCountryCode(phone_number) {
    const countryCode = extractCountryCode(phone_number)
    return countryCode !== null && countryCodeMap[countryCode] !== undefined
}

export const getTokenFromUrl = () => {
    const urlParams = new URLSearchParams(window.location.search);
    return urlParams.get('token');
};

export const isValidToken = (token) => {
    if (!token) return false;

    try {
        const parts = token.split('.');
        if (parts.length !== 3) return false;

        return true;
    } catch (error) {
        return false;
    }
};

export const removeTokenFromUrl = () => {
    const url = new URL(window.location);
    url.searchParams.delete('token');
    window.history.replaceState({}, document.title, url.pathname + url.search);
};

