export const obfuscateEmail = (email) => {
    if (!email || typeof email !== 'string') {
        return '...';
    }

    const [local, domain] = email.split('@');

    if (!local || !domain) {
        return '...';
    }

    let obfuscatedLocal = local.charAt(0);
    if (local.length > 2) {
        obfuscatedLocal += '***' + local.charAt(local.length - 1);
    } else {
        obfuscatedLocal = local.padEnd(local.length, '*');
    }


    const domainParts = domain.split('.');
    const extension = domainParts.pop(); 
    const namePart = domainParts.join('.');

    let obfuscatedDomainName = namePart.charAt(0);
    if (namePart.length > 2) {
        obfuscatedDomainName += '******';
    }

    return `${obfuscatedLocal}@${obfuscatedDomainName}.${extension}`;
};